:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --correct: #4ecca3;
  --wrong: #e94560;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #0f3460 0%, transparent 30%),
                    radial-gradient(circle at 80% 70%, #0f3460 0%, transparent 30%);
  background-attachment: fixed;
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  line-height: 1.5;
}

.card {
  background-color: var(--card-bg);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  image-rendering: pixelated;
}

h1 {
  font-size: 28px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--highlight);
  text-shadow: 2px 2px 0 #000;
  margin-bottom: 8px;
  text-align: center;
}

.subtitle {
  font-size: 16px;
  text-align: center;
  margin-bottom: 24px;
  color: #aaa;
}

.target {
  font-size: 20px;
  letter-spacing: 1px;
  margin-bottom: 24px;
  padding: 16px;
  background-color: #0d1b2a;
  border: 2px solid var(--accent);
  min-height: 80px;
  word-break: break-word;
  line-height: 1.6;
}

.target span {
  display: inline;
}

.target .correct {
  color: var(--correct);
}

.target .wrong {
  color: var(--wrong);
  text-decoration: underline;
  text-decoration-style: wavy;
}

.target .current {
  background-color: var(--accent);
  outline: 2px solid var(--highlight);
}

.label {
  display: block;
  font-size: 16px;
  margin-bottom: 8px;
  color: var(--text);
}

.input {
  width: 100%;
  padding: 12px 16px;
  font-family: var(--font);
  font-size: 18px;
  background-color: #0d1b2a;
  border: 3px solid var(--accent);
  color: var(--text);
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

.input:focus {
  border-color: var(--highlight);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.input::placeholder {
  color: #555;
}

.accuracy {
  font-size: 20px;
  margin: 16px 0;
  min-height: 30px;
  text-align: center;
  font-weight: bold;
  color: var(--highlight);
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 14px 24px;
  font-family: var(--font);
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 1px;
  background-color: var(--accent);
  color: var(--text);
  border: 3px solid var(--highlight);
  cursor: pointer;
  transition: background-color 0.1s, transform 0.1s;
  box-shadow: 4px 4px 0 #000;
}

.btn:hover {
  background-color: var(--highlight);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--correct);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

@media (max-width: 400px) {
  body {
    font-size: 16px;
    padding: 8px;
  }
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 22px;
  }
  .target {
    font-size: 18px;
    padding: 12px;
  }
  .input {
    font-size: 16px;
    padding: 10px 12px;
  }
  .btn {
    font-size: 16px;
    padding: 12px 16px;
  }
}

const targetEl = document.getElementById('target');
const inputEl = document.getElementById('input');
const accuracyEl = document.getElementById('accuracy');
const restartBtn = document.getElementById('restart');

const SENTENCE = 'The quick brown fox jumps over the lazy dog.';
let targetChars = [];
let finished = false;

function renderTarget() {
  targetEl.innerHTML = '';
  targetChars = SENTENCE.split('').map((ch, i) => {
    const span = document.createElement('span');
    span.textContent = ch;
    span.dataset.index = i;
    targetEl.appendChild(span);
    return span;
  });
}

function updateHighlight() {
  const typed = inputEl.value;
  let correctCount = 0;
  for (let i = 0; i < targetChars.length; i++) {
    const span = targetChars[i];
    span.classList.remove('correct', 'wrong', 'current');
    if (i < typed.length) {
      if (typed[i] === SENTENCE[i]) {
        span.classList.add('correct');
        correctCount++;
      } else {
        span.classList.add('wrong');
      }
    } else if (i === typed.length) {
      span.classList.add('current');
    }
  }
  if (!finished) {
    accuracyEl.textContent = '';
  }
  return correctCount;
}

function checkCompletion() {
  const typed = inputEl.value;
  if (typed.length >= SENTENCE.length) {
    finished = true;
    inputEl.disabled = true;
    const correct = updateHighlight();
    const percent = Math.round((correct / SENTENCE.length) * 100);
    accuracyEl.textContent = `Accuracy: ${percent}%`;
    restartBtn.focus();
  }
}

function reset() {
  finished = false;
  inputEl.disabled = false;
  inputEl.value = '';
  accuracyEl.textContent = '';
  renderTarget();
  updateHighlight();
  inputEl.focus();
}

inputEl.addEventListener('input', () => {
  if (finished) return;
  updateHighlight();
  checkCompletion();
});

restartBtn.addEventListener('click', reset);

reset();
